<?php require_once 'config/config.php';require_login();$title='Request Service';include 'includes/header.php';$services=db()->query('SELECT * FROM services WHERE status=1')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$file=null;if(!empty($_FILES['attachment']['name'])){if($_FILES['attachment']['size']>5*1024*1024) {flash('danger','File too large.');header('Location: service_request.php');exit;} $allowed=['pdf','jpg','jpeg','png','mp4'];$ext=strtolower(pathinfo($_FILES['attachment']['name'],PATHINFO_EXTENSION));if(!in_array($ext,$allowed)) {flash('danger','Invalid file type.');header('Location: service_request.php');exit;} $file=uniqid('ref_',true).'.'.$ext;move_uploaded_file($_FILES['attachment']['tmp_name'],'uploads/'.$file);}$st=db()->prepare('INSERT INTO service_requests(customer_id,service_id,project_title,description,location,preferred_date,budget,attachment) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$_SESSION['user']['user_id'],$_POST['service_id'],$_POST['project_title'],$_POST['description'],$_POST['location'],$_POST['preferred_date']?:null,$_POST['budget']?:null,$file]);flash('success','Service request submitted successfully.');header('Location: customer/requests.php');exit;}?><section class="section"><div class="container" style="max-width:850px"><p class="gold">SERVICE REQUEST / BOOKING</p><h1>Tell us about your project</h1><?php show_flash();?><form method="post" enctype="multipart/form-data" class="card p-4 mt-4"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="row g-3"><div class="col-md-6"><label>Service</label><select name="service_id" class="form-select" required><?php foreach($services as $s):?><option value="<?=$s['service_id']?>" <?=($_GET['service_id']??'')==$s['service_id']?'selected':''?>><?=e($s['service_name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Project title</label><input name="project_title" class="form-control" required></div><div class="col-md-6"><label>Location</label><input name="location" class="form-control" placeholder="Addis Ababa"></div><div class="col-md-3"><label>Preferred date</label><input type="date" name="preferred_date" class="form-control"></div><div class="col-md-3"><label>Budget (ETB)</label><input type="number" step="0.01" name="budget" class="form-control"></div><div class="col-12"><label>Description</label><textarea name="description" class="form-control" rows="6" required></textarea></div><div class="col-12"><label>Reference file (PDF/JPG/PNG/MP4, max 5MB)</label><input type="file" name="attachment" class="form-control"></div></div><button class="btn btn-gold mt-4">Submit Request</button></form></div></section><?php include 'includes/footer.php';?>
